package study.embed;

import org.apache.catalina.startup.Tomcat;

public class EmbeddedTomcatMain {

    public static void main(String[] args) throws Exception {
        System.out.println("1. main 시작 " + Thread.currentThread().getName());

        Tomcat tomcat = new Tomcat();
        System.out.println("2. 객체를 만들었다");

        tomcat.setPort(8080);
        System.out.println("3. 포트를 정했다");

        tomcat.addContext("", "/");
        System.out.println("4. 컨텍스트를 붙였다");

        tomcat.start();
        System.out.println("5. start() 가 돌아왔다");

        tomcat.getServer().await();
        System.out.println("6. await 가 끝났다");
    }
}

