-- 포트가 언제 열리나

public static void main(String[] args) throws Exception {
    Tomcat tomcat = new Tomcat();
    tomcat.setPort(8080);
    tomcat.addContext("", "/");

    System.out.println("start 전: " + isOpen(8080));
    tomcat.start();
    System.out.println("start 후: " + isOpen(8080));

    tomcat.getServer().await();
}

static boolean isOpen(int port) {
    try (var s = new java.net.Socket("localhost", port)) {
        return true;
    } catch (Exception e) {
        return false;
    }
}

