public static void main(String[] args) throws Exception {
    for (int port : new int[]{8080, 8081}) {
        Tomcat t = new Tomcat();
        t.setPort(port);
        t.setBaseDir("/tmp/tomcat-" + port);
        t.addContext("", "/");
        t.start();
        System.out.println("떴다: " + t.getConnector().getLocalPort());
    }
    Thread.currentThread().join();
}

